/* Radio Argentina — Offline WebGL Engine (THREE-compatible subset, zero CDN) */
(function (global) {
  "use strict";
  const AdditiveBlending = 2;

  function hexToRgb(hex) {
    return [((hex >> 16) & 255) / 255, ((hex >> 8) & 255) / 255, (hex & 255) / 255];
  }

  class Clock {
    constructor() { this.start = performance.now(); }
    getElapsedTime() { return (performance.now() - this.start) * 0.001; }
  }

  class BufferAttribute {
    constructor(array, itemSize) { this.array = array; this.itemSize = itemSize; this.needsUpdate = true; }
  }

  class BufferGeometry {
    constructor() { this.attributes = {}; this._buf = null; }
    setAttribute(name, attr) { this.attributes[name] = attr; return this; }
    dispose() { this._buf = null; }
  }

  class PointsMaterial {
    constructor(opts = {}) {
      this.color = opts.color ?? 0xffc96a;
      this.size = opts.size ?? 6;
      this.opacity = opts.opacity ?? 0.8;
      this.blending = opts.blending ?? AdditiveBlending;
    }
    dispose() {}
  }

  class Points {
    constructor(geometry, material) { this.geometry = geometry; this.material = material; this.isPoints = true; }
  }

  class TorusGeometry {
    constructor(radius, tube, radialSegments, tubularSegments) {
      this.radius = radius; this.tube = tube; this.segments = tubularSegments || 64;
    }
    dispose() {}
  }

  class MeshBasicMaterial {
    constructor(opts = {}) {
      this.color = opts.color ?? 0xffd985;
      this.opacity = opts.opacity ?? 0.25;
      this.blending = opts.blending ?? AdditiveBlending;
    }
    dispose() {}
  }

  class Mesh {
    constructor(geometry, material) {
      this.geometry = geometry; this.material = material; this.isMesh = true;
      this.position = { x: 0, y: 0, z: 0, set: function (x, y, z) { this.x = x; this.y = y; this.z = z; } };
      this.rotation = { x: 0, y: 0, z: 0 };
      this.scale = { x: 1, y: 1, z: 1, setScalar: function (s) { this.x = this.y = this.z = s; } };
    }
  }

  class Group {
    constructor() { this.children = []; this.isGroup = true; }
    add(obj) { this.children.push(obj); return this; }
  }

  class Scene extends Group {}

  class OrthographicCamera {
    constructor(left, right, top, bottom) {
      this.left = left; this.right = right; this.top = top; this.bottom = bottom;
      this.position = { x: 0, y: 0, z: 10 };
    }
  }

  class WebGLRenderer {
    constructor(opts = {}) {
      this.canvas = opts.canvas;
      this.dpr = 1;
      const gl = this.canvas.getContext("webgl", { alpha: true, antialias: !!opts.antialias, premultipliedAlpha: true });
      if (!gl) throw new Error("WebGL not available");
      this.gl = gl;
      this._initShaders();
    }
    _compile(type, src) {
      const gl = this.gl, s = gl.createShader(type);
      gl.shaderSource(s, src); gl.compileShader(s);
      return s;
    }
    _initShaders() {
      const gl = this.gl;
      const pVert = `
        attribute vec3 aPos;
        uniform vec2 uRes;
        uniform float uSize;
        void main() {
          vec2 clip = (aPos.xy / uRes) * 2.0 - 1.0;
          gl_Position = vec4(clip.x, -clip.y, 0.0, 1.0);
          gl_PointSize = uSize;
        }`;
      const pFrag = `
        precision mediump float;
        uniform vec3 uColor;
        uniform float uOpacity;
        void main() {
          vec2 c = gl_PointCoord - vec2(0.5);
          float d = length(c) * 2.0;
          if (d > 1.0) discard;
          float glow = pow(1.0 - d, 2.2);
          gl_FragColor = vec4(uColor * glow * uOpacity, glow * uOpacity);
        }`;
      this.pProg = gl.createProgram();
      gl.attachShader(this.pProg, this._compile(gl.VERTEX_SHADER, pVert));
      gl.attachShader(this.pProg, this._compile(gl.FRAGMENT_SHADER, pFrag));
      gl.linkProgram(this.pProg);

      const rVert = `
        attribute vec2 aPos;
        uniform vec2 uRes;
        uniform vec2 uCenter;
        uniform float uScale;
        uniform float uRot;
        void main() {
          float cs = cos(uRot), sn = sin(uRot);
          vec2 p = vec2(aPos.x * cs - aPos.y * sn, aPos.x * sn + aPos.y * cs) * uScale + uCenter;
          vec2 clip = (p / uRes) * 2.0 - 1.0;
          gl_Position = vec4(clip.x, -clip.y, 0.0, 1.0);
        }`;
      const rFrag = `
        precision mediump float;
        uniform vec3 uColor;
        uniform float uOpacity;
        void main() {
          gl_FragColor = vec4(uColor * uOpacity, uOpacity);
        }`;
      this.rProg = gl.createProgram();
      gl.attachShader(this.rProg, this._compile(gl.VERTEX_SHADER, rVert));
      gl.attachShader(this.rProg, this._compile(gl.FRAGMENT_SHADER, rFrag));
      gl.linkProgram(this.rProg);
    }
    setPixelRatio(r) { this.dpr = r || 1; }
    setSize(w, h) {
      this.width = w; this.height = h;
      this.canvas.width = Math.round(w * this.dpr);
      this.canvas.height = Math.round(h * this.dpr);
      this.gl.viewport(0, 0, this.canvas.width, this.canvas.height);
    }
    setClearColor() { this.gl.clearColor(0, 0, 0, 0); }
    render(scene, camera) {
      const gl = this.gl;
      gl.clear(gl.COLOR_BUFFER_BIT);
      gl.enable(gl.BLEND);
      gl.blendFunc(gl.ONE, gl.ONE);
      const resX = camera.right - camera.left;
      const resY = Math.abs(camera.bottom - camera.top);

      const drawNode = (node) => {
        if (node.isGroup) { node.children.forEach(drawNode); return; }
        if (node.isPoints) {
          const pos = node.geometry.attributes.position;
          if (!node.geometry._buf) node.geometry._buf = gl.createBuffer();
          gl.bindBuffer(gl.ARRAY_BUFFER, node.geometry._buf);
          if (pos.needsUpdate) { gl.bufferData(gl.ARRAY_BUFFER, pos.array, gl.DYNAMIC_DRAW); pos.needsUpdate = false; }
          gl.useProgram(this.pProg);
          const loc = gl.getAttribLocation(this.pProg, "aPos");
          gl.enableVertexAttribArray(loc);
          gl.vertexAttribPointer(loc, 3, gl.FLOAT, false, 0, 0);
          gl.uniform2f(gl.getUniformLocation(this.pProg, "uRes"), resX, resY);
          gl.uniform1f(gl.getUniformLocation(this.pProg, "uSize"), node.material.size * this.dpr);
          const rgb = hexToRgb(node.material.color);
          gl.uniform3f(gl.getUniformLocation(this.pProg, "uColor"), rgb[0], rgb[1], rgb[2]);
          gl.uniform1f(gl.getUniformLocation(this.pProg, "uOpacity"), node.material.opacity);
          gl.drawArrays(gl.POINTS, 0, pos.array.length / 3);
        } else if (node.isMesh && node.geometry instanceof TorusGeometry) {
          if (!node.geometry._buf) {
            const seg = node.geometry.segments, r = node.geometry.radius, t = node.geometry.tube;
            const verts = new Float32Array((seg + 1) * 4);
            for (let i = 0; i <= seg; i++) {
              const a = (i / seg) * Math.PI * 2, ca = Math.cos(a), sa = Math.sin(a);
              verts[i * 4] = ca * (r - t); verts[i * 4 + 1] = sa * (r - t);
              verts[i * 4 + 2] = ca * (r + t); verts[i * 4 + 3] = sa * (r + t);
            }
            node.geometry._buf = gl.createBuffer();
            node.geometry._count = (seg + 1) * 2;
            gl.bindBuffer(gl.ARRAY_BUFFER, node.geometry._buf);
            gl.bufferData(gl.ARRAY_BUFFER, verts, gl.STATIC_DRAW);
          } else {
            gl.bindBuffer(gl.ARRAY_BUFFER, node.geometry._buf);
          }
          gl.useProgram(this.rProg);
          const loc = gl.getAttribLocation(this.rProg, "aPos");
          gl.enableVertexAttribArray(loc);
          gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);
          gl.uniform2f(gl.getUniformLocation(this.rProg, "uRes"), resX, resY);
          gl.uniform2f(gl.getUniformLocation(this.rProg, "uCenter"), node.position.x, node.position.y);
          gl.uniform1f(gl.getUniformLocation(this.rProg, "uScale"), node.scale.x);
          gl.uniform1f(gl.getUniformLocation(this.rProg, "uRot"), node.rotation.z);
          const rgb = hexToRgb(node.material.color);
          gl.uniform3f(gl.getUniformLocation(this.rProg, "uColor"), rgb[0], rgb[1], rgb[2]);
          gl.uniform1f(gl.getUniformLocation(this.rProg, "uOpacity"), node.material.opacity);
          gl.drawArrays(gl.TRIANGLE_STRIP, 0, node.geometry._count);
        }
      };
      drawNode(scene);
    }
    dispose() {}
  }

  global.THREE = {
    AdditiveBlending, Clock, BufferAttribute, BufferGeometry, PointsMaterial, Points,
    TorusGeometry, MeshBasicMaterial, Mesh, Group, Scene, OrthographicCamera, WebGLRenderer
  };
})(window);
